def parse_label(line):
    fields = []
    i = 0
    n = len(line)

    while True:
        field = []
        if i < n and line[i] == '"':
            i += 1
            while True:
                if i == n:
                    raise ValueError('unclosed quote')
                if line[i] == '"':
                    i += 1
                    if i < n and line[i] == '"':
                        field.append('"')
                        i += 1
                    else:
                        break
                else:
                    field.append(line[i])
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError('character after closing quote')
        else:
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError('quote inside unquoted field')
                field.append(line[i])
                i += 1

        fields.append(''.join(field))
        if i == n:
            return fields
        i += 1  # Skip the delimiter; a trailing comma starts an empty field.
```

